DELETE FROM `npc_text_locale` WHERE `ID` = 16185 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16185, 'zhTW', '你現在有三個樣本了。接下來要選哪一個樣本?', '你現在有三種樣本。你接下來會選擇哪個?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16186 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16186, 'zhTW', '你已經有四個樣本了，只剩下一個測試名額。你要選哪一個?', '你有四種樣本，但只有空間再測試一種。你會選擇哪種?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16187 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16187, 'zhTW', '你已經選好全部五個樣本了。', '你已經選擇了全部五種樣本了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16188 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16188, 'zhTW', '你可以用這些燒杯和煉金工具，對各種潛艇燃料進行實驗。', '你可以用這些燒杯和鏈金工具開始你各種海底油的樣本實驗。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16189 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16189, 'zhTW', '你發現了一種新型生物燃料！把它帶去給工程師海克斯克拉布進行測試。', '你創造了一種全新的生質燃料!把這帶給工程師赫克薩克拉來進行測試。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16190 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16190, 'zhTW', '你發現了一種新型生物燃料！把它帶去給費亞斯科·希茲格林進行測試。', '你已經創造了一種新的生質燃料了!將它帶給菲亞斯戈·嘶咧來做測試。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16216 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16216, 'zhTW', '為國王下廚是一種榮耀，不是差事。你有空幫我跑幾趟腿嗎?', '為國王烹飪是個榮譽，不是工作。你有時間來幫我一把嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16250 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16250, 'zhTW', '你想幹嘛?', '你要幹啥?', '我什麼都不會告訴你的！', '我什麼都不會告訴你的！', '滾開。', '滾開。', '喔，大英雄駕到了。我得救啦！是啊，才怪……', '喔，大英雄駕到了。我得救啦！是啊，才怪……', '你想聊天?先付錢。', '你想聊天?先付錢。', NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16258 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16258, 'zhTW', '要餵飽一整支部落大軍可不是件容易的事。我有很多事要忙，你有空幫忙嗎?', '要餵飽一整個部落軍隊並不是一件輕鬆的差事。我有很多的事情要做。你有空可以幫我嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16293 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16293, 'zhTW', '麥克利的移山者有限公司的傑瑟普·麥克利，聽候您的差遣。', NULL, '如果你需要搬走一座山，我辦得到。要幫你造一座出來也行。', NULL, '這還不算我做過最大的工程，差得遠呢。這場大災變說不定是我們遇過最棒的事！', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16386 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16386, 'zhTW', '老兄，要去哪?', '要去哪裡，兄弟?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16425 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16425, 'zhTW', '我不能跟你做生意，$c。這是酋長的命令。', '這位$c，我不能跟你做生意。大酋長的命令。', '我沒有任何東西可以賣給你。', '我沒有任何東西可以賣給你。', '滾開，$c！我可不想讓執法者看到我跟你做生意……', '滾開，$c！我可不想讓執法者看到我跟你做生意……', '走開，我可不想讓酋長發現我跟部落有往來。', '走開，我可不想讓酋長發現我跟部落有往來。', '我的貨不賣給部落。不爽?去跟酋長理論啊！', '我的貨不賣給部落。不爽?去跟酋長理論啊！', '酋長莫戈爾下令不准我們跟部落做生意。$B$B<商人憤怒地朝地上吐了口水，但拒絕再多說什麼。>', '酋長莫戈爾下令不准我們跟部落做生意。$B$B<商人憤怒地朝地上吐了口水，但拒絕再多說什麼。>', NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16430 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16430, 'zhTW', '來啊，$r。正好給我的藉口。', NULL, '這裡由酋長莫戈爾說了算。別忘了這點。', NULL, '<執法者的雙眼閃過一道紅光。>$B$B我倒希望你們那可悲的部落來攻打我們。我可等不及要見血了，$c！', NULL, '這股狂怒！這股力量！我這輩子從沒感覺這麼強大過。$B$B很快地，所有龍喉氏族的人都會有和我一樣的感受。', NULL, '別耍花樣，$c。$B$B<執法者的手指緊繃地按在劍柄旁，似乎巴不得你惹出點麻煩。>', NULL, '酋長莫戈爾會讓龍喉氏族再次強大！$B$B我們才不需要你們那可悲的部落。', NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16465 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16465, 'zhTW', '喂!', NULL, 'Avast!', NULL, 'Arr!', NULL, 'Yarr!', NULL, '我的老天爺！真是嚇了我一跳！', NULL, 'Gangway!', NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16470 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16470, 'zhTW', '今天該把帳算清了，$c!', NULL, '你是來幫忙推翻莫戈爾的嗎?', NULL, '扎伊拉說部落會來幫忙！我能做什麼?', NULL, '別給我什麼護甲。給我一把刀，告訴我要殺誰就行。', NULL, '部落來了！我們早就該有個像樣的領導者了。', NULL, '我會與你並肩作戰，$c。你絕不會後悔幫助我們的！', NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16471 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16471, 'zhTW', '看來我挑錯日子停止獵殺邪能獸人了。', '看來我選錯了停止殺魔獄獸人的日子了。', '清算的日子到了，$c！', '清算的日子到了，$c！', '教練，讓我上場！我準備好戰鬥了！', '教練，讓我上場！我準備好戰鬥了！', '今天，莫戈爾的暴政就要結束了。', '今天，莫戈爾的暴政就要結束了。', '就是現在，$c！革命的時刻到了。', '就是現在，$c！革命的時刻到了。', '$c！扎伊拉說部落會提供我們武器。你帶了什麼來?', '$c！扎伊拉說部落會提供我們武器。你帶了什麼來?', NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16488 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16488, 'zhTW', '你想向聖光學習什麼?', '需要聖光教導你什麼?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16491 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16491, 'zhTW', '願日光庇佑你，$c。', '願日光保護你，$c。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16519 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16519, 'zhTW', '吉爾尼斯之戰', '吉爾尼斯之戰', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16520 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16520, 'zhTW', '你的實力還不足以進入「吉爾尼斯之戰」。累積更多經驗後再回來吧。', '你的等級還不足以參加吉爾尼斯之戰的戰鬥。等你獲得更多經驗的時候再回來。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16522 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16522, 'zhTW', '你的實力還不足以在「雙峰山」進行戰鬥。累積更多經驗後再回來吧。', '你的等級還不足以參加雙子峰的戰鬥。等你獲得更多經驗的時候再回來。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16541 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16541, 'zhTW', '準備好訓練了嗎，戰士?', '準備接受訓練了嗎，戰士?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16558 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16558, 'zhTW', '喳喳!', NULL, '奧格瑪現在比以往任何時候都要強大！', NULL, '我能幫上忙嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16560 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16560, 'zhTW', '教徒?我不曉得。不過，我是有看到幾個鬼鬼祟祟的傢伙在南飛艇塔那附近徘徊。', NULL, '我什麼都不知道！去問別人吧。', NULL, '秘密邪教?你是說我在南邊飛艇塔底下看到的那群開會的人嗎?', NULL, '秘密邪教?你該不會跟那些在南邊飛艇塔附近鬼鬼祟祟的怪獸人是一夥的吧?', NULL, '我太笨了，加入不了邪教。自從我從飛艇後面摔下去之後就一直這樣。還撞到那些螺旋槳。落地時撞到一塊石頭。他們用一個金屬碗幫我把頭修得圓圓硬硬的。$B$B<他用拳頭敲了敲自己的腦袋。>$B$B然後閃電就打下來了。', NULL, '我常聽到奇怪的獸人在南邊飛艇塔裡竊竊私語。每次我一靠近，他們就閉嘴了。', NULL, '我不知道。$B$B別打我！', NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16569 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16569, 'zhTW', '我沒辦法幫你訓練。去找一位$c訓練師吧。', '我幫不上忙，請你去找一位$c訓練師。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16570 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16570, 'zhTW', '你是來訓練的嗎，獵人?', '你是來接受訓練的嗎，獵人?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16573 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16573, 'zhTW', '你是來學習考古學的嗎?', '你是來學習考古學的嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16601 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16601, 'zhTW', '有兩個地方：貿易區的商人會館，以及矮人區的暴風城拍賣行。', '總共有兩個:貿易區的貿易大廳，還有位在矮人區的暴風城拍賣場。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16602 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16602, 'zhTW', '你會在矮人區最北邊、靠近北方登陸場的地方找到它。', '它就在矮人區最北邊的小廣場，靠近城北平臺那裡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16603 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16603, 'zhTW', '城裡有兩間銀行：貿易區的暴風城錢莊，以及矮人區的暴風城皇家銀行。', '城裡有兩家銀行:貿易區的暴風城會計室，還有位在矮人區的暴風城皇家銀行。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16604 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16604, 'zhTW', '暴風城皇家銀行位於矮人區最北端，就在北方登陸場的入口內側。', '暴風城皇家銀行位在矮人區的最北邊的小廣場裡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16605 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16605, 'zhTW', '暴風城最受歡迎的兩間旅店分別位於貿易區和矮人區：鍍金玫瑰旅店與金酒桶旅店。', '暴風城兩家最受歡迎的旅店分別坐落在貿易區和矮人區:鑲金玫瑰和黃金酒桶。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16606 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16606, 'zhTW', '金酒桶旅店位於矮人區北部，就在噴泉旁邊。', '黃金酒桶位於矮人區的北側，就在噴泉旁邊。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16607 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16607, 'zhTW', '暴風城有許多值得一看的地方，從深井礦車到暴風城城堡都有。$B$B你在找什麼呢?', '暴風城有許多有趣的景點，從礦道地鐵到暴風要塞，應有盡有。$B$B你想要去哪裡?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16608 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16608, 'zhTW', '舊城區和矮人區都有獸欄管理員。', '舊城區和矮人區都有獸欄管理員。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16609 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16609, 'zhTW', '拜倫·橡角在暴風城最東邊，穿過舊城區後方的大門就能找到他。', '卡利在暴風城的最東邊，穿過舊城區後面的門口就能看到他。', '如果你在訓練另一隻寵物時需要寄放目前的寵物，可以去矮人區找珍諾娃·石盾談談。', '如果你在訓練另一隻寵物時需要寄放目前的寵物，可以去矮人區找珍諾娃·石盾談談。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16617 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16617, 'zhTW', '舊城區的指揮中心和矮人區都有獵人在訓練。', '矮人區和舊城區的指揮所裡頭都有獵人訓練師。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16618 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16618, 'zhTW', '你隨時都能在舊城區東門外找到幾位獵人。', '舊城區的東門外面經常會有些獵人在那邊。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16619 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16619, 'zhTW', '公園……?$B$B它已經變成廢墟了。你沒聽說嗎?巨龍死亡之翼飛越暴風城時，順道就把它給摧毀了。$B$B老實說，我也不曉得他為什麼沒把一切夷為平地，但我們都感謝聖光讓他手下留情。', '花園...?$B$B花園已經毀了，你沒聽說嗎?巨龍死亡之翼在飛過暴風城上空的時候把那裡給毀了。$B$B坦白講，不曉得他為什麼沒有把整座城都給毀了，但是我們全都很感謝聖光，還好他沒有這麼做。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16620 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16620, 'zhTW', '城堡位於暴風城北邊。$B$B只要沿著運河向北走，最後就會看到一座吊橋……那座吊橋通往城堡的庭院。', '要塞坐落在暴風城北。$B$B只要沿著運河往北走，你就會經過一座吊橋...通往要塞的中庭。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16621 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16621, 'zhTW', '監獄?你幹嘛想去那裡?它就在城市中央，法師區的東北方。$B$B如果你真的要去，小心點。我聽說那裡發生暴動。', '監獄?為什麼你會想要去那裡?它位在暴風城的正中間，就在法師區的東北邊。$B$B假如你真的想去那裡的話，請多加小心，我有聽到暴動的訊息。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16624 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16624, 'zhTW', '一段時間以來，我們一直收到關於艾澤拉斯各地元素騷動的消息。根據我們的情報來源，這種現象並非完全自然發生，但我們還無法確定其源頭。我們有一些推測，但都還沒有確切證據。$B$B在四處走動時，請留意任何可疑的元素活動。如果你發現什麼值得注意的線索，請告訴大地之環的使者。你可以在任何一座主城中找到我們。$B$B在外要小心。麻煩正在醞釀。', '我們已陸陸續續接到了不少的報告，說有元素在艾澤拉斯各地騷動。而且我們的情報來源還指出，它們並非全是自然發生的現象，只是我們尚未找出明確的成因。我們是有一些理論，但依舊缺乏明確的答案。$B$B當你在外旅行冒險的時候，請睜大眼睛注意是否有任何可疑的元素活動。假如你發現了任何值得關注的訊息，請告知陶土議會的特使。我們在各大主城都有派駐代表。$B$B請你睜大眼睛，動亂正在醞釀。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16627 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16627, 'zhTW', '丹曼家族珠寶店位於貿易區北部與運河區之間，你要找的東西那裡應該都有。', '丹門家族珠寶店，位於北貿易區和運河之間，那應該有你想要的東西。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16628 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16628, 'zhTW', '哈里森·瓊斯不外出考察時，會在暴風城城堡的皇家圖書館教授考古學。', '哈里遜·瓊斯如果沒有出去進行調查，他都會在暴風要塞的皇家圖書館裡教授考古學。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16629 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16629, 'zhTW', '專業技能商人通常都在各自的訓練師附近。其他類型的商人則分散在暴風城各處。$B$B你在找什麼呢?', '專業技能商人一定能在相應的訓練師附近找到。其他的商人則散佈於暴風城各個角落。$B$B你在找的是什麼?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16630 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16630, 'zhTW', '勇士之殿位於舊城區的東南端。$B$B榮譽與征服軍需官都在那裡。', '勇士大廳位於舊城區東南邊的盡頭。$B$B榮譽紋章與征服點數軍需官都在裡頭。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16631 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16631, 'zhTW', '在舊城區東南門外的指揮中心，你可以找到軍需官。', '在指揮所裡，就在舊城區東南門的外面，軍需官就在那邊。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16632 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16632, 'zhTW', '舊城區東南門外不遠處就有獸欄。你可以在那裡找到騎術訓練師和馬匹繁育師。', '舊城區的東南城門外就有一座馬廄，騎術訓練師和馬匹飼養師都在那裡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16634 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16634, 'zhTW', '你知道貿易區旁的獅鷲棲息地嗎?飛行管理員就在那裡。$B$B有兩位蠻錘矮人在那裡飼養和販售獅鷲，甚至還能訓練你騎乘牠們。', '你知道獅鷲獸棲息處其實是在貿易區嗎?就在飛行管理員那裡。$B$B有兩位蠻錘氏族的矮人在那邊飼養和販賣獅鷲獸，甚至還能訓練你該怎樣駕馭牠們。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16635 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16635, 'zhTW', '你看起來筋疲力盡。發生什麼事了嗎?', '你好像很累的樣子。出什麼差錯了嗎?', '很高興見到你。', '很高興見到你。', 'Yes?', 'Yes?', '你找回最後一塊碎片了嗎?', '你找回最後一塊碎片了嗎?', '跟希拉贊恩談得如何?', '跟希拉贊恩談得如何?', '你看起來若有所思。有什麼我能幫忙的嗎?', '你看起來若有所思。有什麼我能幫忙的嗎?', '有需要我幫忙的地方嗎?', '有需要我幫忙的地方嗎?', '我還以為能休息一下呢。真是傻。', '我還以為能休息一下呢。真是傻。');
DELETE FROM `npc_text_locale` WHERE `ID` = 16688 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16688, 'zhTW', '還有更多加茲瑞迪安?你為什麼會覺得我還需要更多這些個鬼東西?我已經堆了快九千個了，而且根本賣不出去!我怎麼會蠢到以為大家會想要買大隻蛇的雕像?呃啊!', NULL, '我看到荒野遊民和他們的首領蠍刺酋長，朝這裡的南邊去了。小心點，他們看起來變強了不少！', NULL, '我看到你這輩子見過最大的蟲子在其中一個希利蘇斯蟲巢附近徘徊。或者其實是兩隻，我也不確定。我想這股熱氣讓我開始神智不清了……你有看到那邊那隻沙貓嗎?', NULL, '我對龍不太了解，但有一天，一隻又大又嚇人的龍出現在那邊，就在時光之穴入口附近。牠一直在大喊些什麼……是什麼來著……我們所知時間的終結?我當時沒怎麼在聽。', NULL, '我一位叫佛羅克的老朋友本來應該要前往加基森，但他和其餘負責駕船的比爾格沃特船員始終沒有抵達。我聽說南邊遠處有個瘋狂地精，老在一台墜毀的飛行器附近閒晃，難道會是……?', NULL, '我在沙丘間查看「百足希利蘇斯零食」（專利申請中）的獲利潛力時，發現了一輛壞掉的推車。我心想，「嘿，免費的推車！」結果沒想到，一隻你這輩子見過最大的蛇怪冒了出來，我只好把整輛車都丟下逃跑了！', NULL, '你有看過那些在沙丘底下移動的巨大土堆嗎?牠們屬於一種艾澤拉斯前所未見的鑽地蟲！我相信，像你這樣經驗豐富的冒險者，跟牠們交手一定會是很棒的學習經驗。', NULL, '大災變發生時，束縛艾澤拉斯各地元素生物的鎖鏈大幅減弱。其中一個元素生物──阿奎曼塔斯──已經不再受到囚禁。我聽說牠正在給南海幫派製造不少大麻煩！', NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16705 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16705, 'zhTW', '我可以教你鍛造技藝，也能提供所需的工具。$B$B我能為你做什麼?', '我可以教導你鍛造的技藝，以及提供必要的工具。$B$B有什麼需要我幫忙的嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16706 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16706, 'zhTW', '我可以教你藥草學，也能提供實用的補給品。$B$B我能為你做什麼?', '我可以傳授你草藥學的技藝，以及提供必要的工具。$B$B有什麼需要我幫忙的嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16714 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16714, 'zhTW', '我能怎麼幫你呢，大地之子?', '大地之子，有什麼需要我幫忙的嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16744 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16744, 'zhTW', '你不會是又想來偷我的炸藥了吧?', NULL, '看看這個地方！$B$B這簡直是考古學家的夢想……', NULL, '這次你可別又拿著我的炸藥到處亂跑了，好嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16750 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16750, 'zhTW', '誰知道在那外域黑暗中，有什麼陰暗恐怖的東西正在低語……那些會讓靈魂看了發瘋的東西?$B$B唯有—我們—知道。而你，是來尋求—更多—知識的，對吧?', '誰知道黑暗的外界裡會有什麼深沉又可怕的東西...會把人嚇到失魂落魄的東西?$B$B可是「我們」知道。而且，你來就是想知道「更多」的，對不對?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16751 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16751, 'zhTW', '你好啊，$N。你是來這裡學習隱秘之術的嗎?', '你好，$n。你是來這裡學習隱藏的技藝的嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16763 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16763, 'zhTW', '<咕噥>$B$B你需要什麼嗎，$r?', '<哼>$B$B你需要什麼嗎，$r?', '什麼事?我這裡有點忙。', '什麼事?我這裡有點忙。', '我現在正在訓練。這件事能等等嗎?', '我現在正在訓練。這件事能等等嗎?', 'Yes?', 'Yes?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16771 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16771, 'zhTW', '在死後的世界，我能幫你什麼忙?', '我要如何在此來生中協助你?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16772 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16772, 'zhTW', '在死後的世界，我能幫你什麼忙?', '我要如何在此來生中協助你?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16780 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16780, 'zhTW', '勾裡一直想要當農夫。', NULL, '戈里只是很高興能曬到太陽。', NULL, '戈里想幫忙農場的事。戈里已經有自己的鐮刀了！', NULL, '戈里不太會種東西，但戈里非常會收割。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16784 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16784, 'zhTW', '你可離家老遠了呢，朋友。嘿嘿嘿。\n\n\n\n我能幫你找什麼呢?', '你離家可遠了，老兄。嘿嘿嘿。\n\n我可以幫得上忙嗎?', '這附近可不常見到你這種人呢，朋友。\n\n\n\n我能幫你找什麼呢?', '這附近可不常見到你這種人呢，朋友。\n\n\n\n我能幫你找什麼呢?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16790 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16790, 'zhTW', '抱歉了，$c。$B$B我不認為你有那份天資能夠領悟傳送法術的本質。', '抱歉，$c。$B$B我想你應該沒有足以理解傳送魔法之本質的心智慧力。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16792 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16792, 'zhTW', '拍賣行和銀行就在山谷中央那棟高樓的頂端，朋友。$B$B去找濟濟和馬卡烏吧。', '拍賣場和銀行在谷地中間那個高大建築的最上面，老兄。$B$B去找茲吉和瑪卡於。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16793 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16793, 'zhTW', '你要找的是西嘉比，朋友。$B$B她就在山谷中央那棟高樓裡。', '老兄，希賈姆畢就是你要找的人。$B$B她在谷地中間那棟高樓裡面。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16794 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16794, 'zhTW', '就在山谷旅店外面，朋友。$B$B那是中央那棟高樓。', '就在這座谷地的旅店外面，老兄。$B$B中間最高的那一棟樓。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16795 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16795, 'zhTW', '你在找哪一位呢?', '你是要找哪一個?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16798 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16798, 'zhTW', '你要找的是塞塞比，朋友。$B$B她最常在老漁夫烏姆貝托旁邊的樹下睡覺，看起來就像一隻老虎。', '你該去找沙沙比，老兄。$B$B她通常在漁夫老昂貝託旁邊的樹下睡覺，像一隻大老虎。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16799 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16799, 'zhTW', '庫扎里和贊加正在山谷東南端的一座小島上訓練狩獵者，朋友。', '老兄，卡札裡和贊迦正在精神谷東南邊盡頭的一座小島上訓練獵頭者。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16800 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16800, 'zhTW', '他們在山谷東南端那棟高樓的頂端。', '他們在谷的東南邊那棟很高的建築物頂樓。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16803 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16803, 'zhTW', '暗影行者祖魯可以幫你。$B$B你能在東南方那棟較高建築的最底層找到他。', '暗影行者祖魯可以幫你。$B$B你可以在東南邊那棟較高的房子的最底層找到他。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16804 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16804, 'zhTW', '你要找的是夜行者庫南吉。$B$B他就在山谷中央建築的北邊。', '暗夜潛獵者庫南吉就是你想要找的人。$B$B他就在精神谷中央那棟房子的北邊。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16805 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16805, 'zhTW', '巫醫烏姆布經常在山谷各處走動，照料族人與元素之靈。$B$B到中央建築附近找他吧。', '巫醫烏姆布每天都會在精神谷裡四處行走，照顧此地的人和元素精魂。$B$B到中央那座建築的附近去找他。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16806 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16806, 'zhTW', '你真是瘋了，朋友，居然要碰那種邪門法術。不過我也不會攔你。$B$B恩加里·邪語就在東南方那棟較高的建築裡，過了暗影祭司的神龕就能看到。', '你一定瘋了，老兄，玩弄壞的魔法。但是我不阻止你。$B$B烏恩賈瑞·魔舌在東南邊，經過暗影牧師神廟的那棟高房子裡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16807 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16807, 'zhTW', '贊姬雅是奧格瑪最厲害的廚師，朋友。$B$B你能在山谷中央建築南邊找到她。如果你只是肚子餓，巴坦西也有賣贊姬雅做的食物。', '札姆沙是奧格瑪最棒的廚師，老兄。$B$B你可以在精神谷中央建築的南邊找到她。如果你剛好肚子餓的話，巴塔姆希有在賣札姆沙煮的食物。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16808 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16808, 'zhTW', '詹迪和茲雅拉亞在山谷中央建築北邊的一間小屋裡工作。$B$B不管你需要什麼，他們都能幫上忙，朋友。', '加迪和希爾拉亞工作的地方就在精神谷中央建築的北邊。$B$B你需要什麼他們都可以幫你，老兄。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16810 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16810, 'zhTW', '老烏姆貝托在山谷中央建築東邊的一座小島上。', '老昂貝託就在精神谷中央建築東邊的小島上。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16811 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16811, 'zhTW', '胡朱和贊圖能照顧你的需求。$B$B去山谷中央建築找他們吧，朋友。', '胡鳩和克森圖有你要的東西。$B$B他們就在精神谷中央建築裡面，老兄。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16813 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16813, 'zhTW', '贊提什和他的蛇群正在山谷中央建築附近游走呢，朋友。', '克薩迪斯跟他的蛇就在精神谷中間那棟房子裡面爬來爬去，老兄。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16829 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16829, 'zhTW', '這對艾澤拉斯來說是個嚴峻的時刻，$n。', '這是艾澤拉斯艱難的時期，$n。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16851 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16851, 'zhTW', '我沒辦法保證你能安穩休息，$c。這些獸人根本不知道什麼時候該罷手。', '我無法保證你能夠不受干擾地休息，$c。這些獸人不知道何時才會離開。', '喝醉的獸人已經夠讓人開眼界了。一整支喝醉的獸人大軍，我這輩子都不想再看第二次。', '喝醉的獸人已經夠讓人開眼界了。一整支喝醉的獸人大軍，我這輩子都不想再看第二次。', '如果我母親早告訴我會有這種日子，我肯定不會相信她。', '如果我母親早告訴我會有這種日子，我肯定不會相信她。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16870 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16870, 'zhTW', '你和你的錢，永遠都是這裡的座上賓。', '這裡「永遠」歡迎你和你的錢。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16872 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16872, 'zhTW', '她卡在瓦礫堆裡了，我的蒸汽壓力也沒了。這種地形簡直要命！$B$B你能幫我們脫困嗎?', '它被卡住了，而且我也沒有蒸汽動力了。這種地形簡直要人命啊!$B$B你可以幫我們脫困嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16878 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16878, 'zhTW', '無意冒犯，但你看起來連馱貨科多獸的側面都射不中。$B$B我們別再浪費彼此的時間了，你還是去找對的訓練師吧。', '恕我直言，但是你恐怕連只科多獸的側面都射不中。$B$B別浪費彼此的時間，去找個適合你的訓練師吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16879 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16879, 'zhTW', '嘿。要不要來練練靶?', '呦，要來射幾箭嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16880 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16880, 'zhTW', '嘿，$N。是來上課的嗎?我可沒那麼多時間……', '嗨，$n。你是來上課的嗎?我可不是整天閒閒沒事...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16881 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16881, 'zhTW', '嘿，你沒學好正統法術可不是我的錯。\n\n\n\n去煩$c訓練師吧，好嗎?', '嘿，你學不會法術又不是「我」的錯。\n\n找個$c訓練師去煩，好嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16883 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16883, 'zhTW', '我老遠就聽到你來了，朋友。看來你還需要多練練?', '我大老遠就聽到你走過來的聲音了，老兄。看來你還需要更進一步的訓練?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16884 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16884, 'zhTW', '什麼?我看起來像$c嗎?$B$B快滾吧，好嗎?', '什麼?你以為我是個$c?$B$B請你走開好嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16886 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16886, 'zhTW', '你需要什麼嗎?$B$B真可惜。我沒什麼能給你的，$c。', '你需要什麼嗎?$B$B可惜，我沒有東西可以教你，$c。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16887 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16887, 'zhTW', '「操縱元素，既有趣又賺錢。」$B$B這才是重點，對吧?來，開始幹活吧。', '「好玩又好賺的元素操控法」。$B$B重點就是這樣，我說的沒錯吧?讓我們開始吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16888 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16888, 'zhTW', '聽著。你根本不會想知道我能教你什麼東西。$B$B真的。那會把你的腦子融化。去別的地方乖乖玩吧。', '聽著，你連想都不會想知道我可以教你的是什麼東西。$B$B說真的，那會害你的腦袋融化掉。到別地方去找點簡單的題材吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16889 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16889, 'zhTW', '你不得不愛上邪能：便宜、可再生，而且保證能把東西炸個粉碎。$B$B當然啦，你得冒著把自己永恆的意志輸給時空之外那些難以想像的恐怖存在的風險，不過嘛，有風險才有回報嘛！$B$B好了，你來找我是想談什麼事呢，嗯?', '你一定會超愛魔化能量的:便宜，可一用再用，而且肯定能炸掉東西。$B$B當然啦，你得冒著永遠失去自我意志給超越時空之難以想像之恐懼的後果，但是嘿嘿，有得必有失嘛!$B$B好啦，你來找我是要幹嘛呢?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16946 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16946, 'zhTW', NULL, '將來我想在聖光之願禮拜堂開一家店。雖然我不是什麼厲害的戰士，但那可不表示我無法為理念貢獻一己之力。', NULL, '我跟這些夥伴一起上路的時間並不長，但我已經沒辦法想像少了他們任何一個的生活了。', NULL, '希望你別跟我的貨車客氣。如果我們沒在用的東西，你儘管拿去用就是了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16947 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16947, 'zhTW', NULL, '他幹嘛要那樣子跑掉?!', NULL, '答應我你會找到他，$N。', NULL, '<菲歐娜看起來相當沮喪，她似乎沒有心情說話。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16948 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16948, 'zhTW', NULL, '真高興又見到你，$n!', NULL, '嘿，$N！你是來拜訪的，還是想買點什麼?', NULL, '哎呀呀……這不是你嗎！', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16984 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16984, 'zhTW', '如果你在找秘法重鑄師，法師區外的附魔店裡有一位上層精靈法師。', '若是你要找位秘法重鑄師，在法師區外頭的附魔商店裡就有一位精靈貴族法師。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16988 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16988, 'zhTW', '可憐的孩子，你一定累壞了。$B$B這裡有吃有喝，如果你願意，這裡也很安全，可以好好休息。', '可憐的人，你一定累壞了。$B$B如果你需要，我們這有食物和水，也可在這休息，這是安全的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16989 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16989, 'zhTW', '想吃點東西嗎，$c?$B$B還是只想找個地方讓疲憊的身軀休息一下?', '想吃點東西嗎，$c?$B$B還是隻想歇歇你一身的累骨頭?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 16996 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16996, 'zhTW', '嘿。$B$B你是來寄放寵物的，還是在找走失的同伴?', '呦。$B$B你是來寄放寵物的，還是來尋找失蹤的夥伴?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
